B.acj=s(['\uc815\ud574 \ub454 \uc2dc\uac04\uc5d0 "\uacf5\ubd80\ud560 \uc2dc\uac04\uc774\uc57c"\ub77c\uace0 \uc54c\ub824 \uc8fc\uae30 \uc704\ud574\uc11c\ub9cc \uc368\uc694. \uc2dc\ud5d8 \ub0a0\uc9dc\uac00 \ub2e4\uac00\uc624\uba74 \ub0a8\uc740 \ub0a0\uc744 \uc54c\ub824 \uc8fc\ub294 \ub370\uc5d0\ub3c4 \uc368\uc694.',"\uc54c\ub9bc\uc740 \uae30\uae30 \uc548\uc5d0\uc11c \ub9cc\ub4e4\uc5b4\uc838\uc694. \uc54c\ub9bc\uc744 \ub9cc\ub4e4\ub824\uace0 \uc678\ubd80 \uc11c\ubc84\uc5d0 \ubb34\uc5b8\uac00\ub97c \ubcf4\ub0b4\uc9c0 \uc54a\uc544\uc694.","\uc54c\ub9bc\uc744 \ubc1b\uace0 \uc2f6\uc9c0 \uc54a\uc73c\uba74 \uc124\uc815\uc5d0\uc11c \ub044\uac70\ub098, \uae30\uae30\uc758 \uc54c\ub9bc \uad8c\ud55c\uc744 \uaebc\ub3c4 \uc571\uc740 \uadf8\ub300\ub85c \uc4f8 \uc218 \uc788\uc5b4\uc694."],t.s)
B.amM=new A.l8("3. \uc54c\ub9bc \uad8c\ud55c\uc740 \uc65c \ud544\uc694\ud55c\uac00\uc694",B.acj)
B.aaY=s(["iPhone\uc758 iCloud \ubc31\uc5c5\uc774\ub098 Android\uc758 \uc790\ub3d9 \ubc31\uc5c5\uc744 \ucf1c \ub450\uba74, \uc6b4\uc601\uccb4\uc81c\uac00 \uc571 \ub370\uc774\ud130\ub97c \ubc31\uc5c5\uc5d0 \ud568\uaed8 \ub2f4\uc744 \uc218 \uc788\uc5b4\uc694.","\uc774 \ubc31\uc5c5\uc740 \uc560\ud50c\uc774\ub098 \uad6c\uae00\uc774 \uc5ec\ub7ec\ubd84\uc758 \uacc4\uc815\uc5d0\uc11c \uad00\ub9ac\ud558\ub294 \uac83\uc774\uace0, \uc6b0\ub9ac\uac00 \uadf8 \ub0b4\uc6a9\uc744 \ubcf4\uac70\ub098 \uac00\uc838\uc62c \uc218\ub294 \uc5c6\uc5b4\uc694.","\ubc31\uc5c5\uc5d0 \ub2f4\uae30\uc9c0 \uc54a\uac8c \ud558\ub824\uba74 \uae30\uae30 \uc124\uc815\uc5d0\uc11c \uc774 \uc571\uc758 \ubc31\uc5c5\uc744 \uaebc \uc8fc\uc138\uc694."],t.s)
B.amR=new A.l8("4. \uae30\uae30 \uc790\ub3d9 \ubc31\uc5c5",B.aaY)
B.acE=s(["\uc571\uc740 \uc2dc\ud5d8 \uc77c\uc815\uc744 \ucd5c\uc2e0\uc73c\ub85c \uc720\uc9c0\ud558\ub824\uace0 \uc815\ud574\uc9c4 \uc8fc\uc18c\uc758 \uc791\uc740 \ud30c\uc77c \ud558\ub098\ub97c \ub0b4\ub824\ubc1b\uc544\uc694. \uc6f9\uc5d0\uc11c\ub294 \uc0c8 \ubc84\uc804\uc774 \ub098\uc654\ub294\uc9c0 \ud655\uc778\ud558\ub294 \ud30c\uc77c\ub3c4 \ud568\uaed8 \ud655\uc778\ud574\uc694.",'\uc774\ub54c \ubcf4\ub0b4\ub294 \uac74 "\uadf8 \ud30c\uc77c\uc744 \uc8fc\uc138\uc694"\ub77c\ub294 \uc694\uccad\ubfd0\uc774\uc5d0\uc694. \ud559\uc2b5 \uae30\ub85d\uc774\ub098 \uae30\uae30 \uc548\uc758 \uc815\ubcf4\ub294 \ud568\uaed8 \ubcf4\ub0b4\uc9c0 \uc54a\uc544\uc694.',"\ub2e4\ub9cc \uc778\ud130\ub137 \uc694\uccad\uc740 \uadf8 \ud30c\uc77c\uc744 \ubcf4\uad00\ud558\ub294 \ud638\uc2a4\ud305 \ud68c\uc0ac\uc758 \uc11c\ubc84\ub97c \uac70\uce58\uae30 \ub54c\ubb38\uc5d0, \uc811\uc18d \uc2dc\uac01\uacfc IP \uc8fc\uc18c \uac19\uc740 \uc811\uc18d \uae30\ub85d\uc774 \uadf8 \ud68c\uc0ac \ucabd\uc5d0 \uc7a0\uc2dc \ub0a8\uc744 \uc218 \uc788\uc5b4\uc694. \uc774 \uae30\ub85d\uc740 \uc6b0\ub9ac\uac00 \ub9cc\ub4e4\uc9c0\ub3c4 \ubcf4\uad00\ud558\uc9c0\ub3c4 \uc54a\uc544\uc694."],t.s)
B.amL=new A.l8("5. \uc778\ud130\ub137\uc744 \uc4f0\ub294 \uc21c\uac04",B.acE)
B.acI=s(['"\uc790\ub791\ud558\uae30"\uc5d0\uc11c \ub9cc\ub4e0 \uae30\ub85d\uc99d \uc774\ubbf8\uc9c0\ub098 \ud559\uc2b5 \uae30\ub85d \ud30c\uc77c\uc740 \uc5ec\ub7ec\ubd84\uc774 \uc9c1\uc811 \ub0b4\ubcf4\ub0bc \ub54c\ub9cc \uae30\uae30 \ubc16\uc73c\ub85c \ub098\uac00\uc694.',"\ub0b4\ubcf4\ub0b4\uae30\ub97c \ub204\ub974\uba74 \uae30\uae30\uc758 \uacf5\uc720 \ucc3d\uc774 \uc5f4\ub9ac\uace0, \uac70\uae30\uc11c \uace0\ub978 \uc571(\uba54\uc2dc\uc9c0, \uc0ac\uc9c4\ucca9 \ub4f1)\uc73c\ub85c\ub9cc \uc804\ub2ec\ub3fc\uc694. \uc6b0\ub9ac \uc11c\ubc84\ub85c\ub294 \uc544\ubb34\uac83\ub3c4 \uac00\uc9c0 \uc54a\uc544\uc694.","\uae30\ub85d\uc99d \uc774\ubbf8\uc9c0\uc5d0\ub294 \uc774\ub984\uc774\ub098 \uc5f0\ub77d\ucc98\uac00 \ub4e4\uc5b4\uac00\uc9c0 \uc54a\uc544\uc694."],t.s)
